      "fn": "sceneUpdateBoss",
      "line": 12737,
      "source": "private updateBoss(): void {\n    const run = this.bossRun;\n    if (!run) return;\n    if (!this.actors.some(a => !a.dead && a.defId === run.bossId)) {\n      const ghost = new Actor('gone', 'enemy', vec(run.anchor.x, run.anchor.y));\n      ghost.defId = run.bossId;\n      this.restoreArena(ghost);\n      this.arenaWash = null;\n    }\n  }",
      "output": "export function sceneUpdateBoss(nativeHost:NativeSceneFrameHost): void {\n    const run = nativeHost.bossRun;\n    if (!run) return;\n    if (!nativeHost.actors.some(a => !a.dead && a.defId === run.bossId)) {\n      const ghost = new Actor('gone', 'enemy', vec(run.anchor.x, run.anchor.y));\n      ghost.defId = run.bossId;\n      nativeHost.restoreArena(ghost);\n      nativeHost.arenaWash = null;\n    }\n  }",
