      "source": "private insideCount(e: ActiveEncounter): number {\n    // SOVEREIGNTY: census — a count (the derived census, probe_tiers RIG T).\n    let n = 0;\n    for (const a of this.actors) {\n      if (a.dead || a.team !== 'enemy') continue;\n      if (dist(a.pos, e.pos) - a.radius <= e.radius) n++;\n    }\n    return n;\n  }",
      "output": "export function sceneInsideCount(nativeHost:NativeSceneFrameHost, e: ActiveEncounter): number {\n    // SOVEREIGNTY: census — a count (the derived census, probe_tiers RIG T).\n    let n = 0;\n    for (const a of nativeHost.actors) {\n      if (a.dead || a.team !== 'enemy') continue;\n      if (dist(a.pos, e.pos) - a.radius <= e.radius) n++;\n    }\n    return n;\n  }",
