      "output": "export function sceneBeginCollapse(nativeHost:NativeSceneFrameHost, e: ActiveEncounter): void {\n    const v = e.def.veil!;\n    const run = e.veil!;\n    e.phase = 'collapsing';\n    run.collapseFrom = Math.max(1, e.radius);\n    run.pending.length = 0;\n    nativeHost.text(vec(e.pos.x, e.pos.y - 30), v.text.collapse, e.def.trigger.color, 18);\n  }",
