      "source": "private updateBoroughRefugees(dt: number): void {\n    if (!this.boroughRefugees.length) return;\n    for (let i = this.boroughRefugees.length - 1; i >= 0; i--) {\n      const r = this.boroughRefugees[i];\n      const a = this.actorById(r.id);\n      if (!a || a.dead) { this.boroughRefugees.splice(i, 1); continue; }\n      a.facing = angleTo(a.pos, r.goal);\n      this.moveActor(a, r.goal.x - a.pos.x, r.goal.y - a.pos.y, dt);\n      if (dist(a.pos, r.goal) < r.arrive) {\n        this.slipAway(a, '');\n        this.boroughRefugees.splice(i, 1);\n      }\n    }\n  }",
      "output": "export function sceneUpdateBoroughRefugees(nativeHost:NativeSceneFrameHost, dt: number): void {\n    if (!nativeHost.boroughRefugees.length) return;\n    for (let i = nativeHost.boroughRefugees.length - 1; i >= 0; i--) {\n      const r = nativeHost.boroughRefugees[i];\n      const a = nativeHost.actorById(r.id);\n      if (!a || a.dead) { nativeHost.boroughRefugees.splice(i, 1); continue; }\n      a.facing = angleTo(a.pos, r.goal);\n      nativeHost.moveActor(a, r.goal.x - a.pos.x, r.goal.y - a.pos.y, dt);\n      if (dist(a.pos, r.goal) < r.arrive) {\n        nativeHost.slipAway(a, '');\n        nativeHost.boroughRefugees.splice(i, 1);\n      }\n    }\n  }",
