      "source": "private fractureFoeCount(): number {\n    let n = 0;\n    for (const a of this.actors) if (!a.dead && a.tag === 'fracture_foe') n++;\n    return n;\n  }",
      "output": "export function sceneFractureFoeCount(nativeHost:NativeSceneFrameHost): number {\n    let n = 0;\n    for (const a of nativeHost.actors) if (!a.dead && a.tag === 'fracture_foe') n++;\n    return n;\n  }",
