      "source": "private extractTemperOf(e: ActiveEncounter): ExtractTemperSpec {\n    const rows = e.def.extract!.swarm.tempers;\n    if (!rows?.length) return CLASSIC_EXTRACT_TEMPER;\n    return rows.find(t => t.id === e.ex?.temper) ?? rows[0];\n  }",
      "output": "export function sceneExtractTemperOf(nativeHost:NativeSceneFrameHost, e: ActiveEncounter): ExtractTemperSpec {\n    const rows = e.def.extract!.swarm.tempers;\n    if (!rows?.length) return CLASSIC_EXTRACT_TEMPER;\n    return rows.find(t => t.id === e.ex?.temper) ?? rows[0];\n  }",
