      "source": "private boroughFolkAlive(e: ActiveEncounter): Actor[] {\n    const out: Actor[] = [];\n    for (const id of e.bo?.folkIds ?? []) {\n      const a = this.actorById(id);\n      if (a && !a.dead) out.push(a);\n    }\n    return out;\n  }",
