      "source": "private heroWithin(p: Vec2, r: number): boolean {\n    // SOVEREIGNTY: census — a count (the derived census, probe_tiers RIG T).\n    for (const s of this.seats) {\n      if (!s.actor.dead && dist(s.actor.pos, p) <= r) return true;\n    }\n    return false;\n  }",
      "output": "export function sceneHeroWithin(nativeHost:NativeSceneFrameHost, p: Vec2, r: number): boolean {\n    // SOVEREIGNTY: census — a count (the derived census, probe_tiers RIG T).\n    for (const s of nativeHost.seats) {\n      if (!s.actor.dead && dist(s.actor.pos, p) <= r) return true;\n    }\n    return false;\n  }",
