      "source": "private extractionEntryPoint(e: ActiveEncounter): Vec2 {\n    return this.swarmEntryPoint(e.pos, e.def.extract!.swarm.entryRadius);\n  }",
      "output": "export function sceneExtractionEntryPoint(nativeHost:NativeSceneFrameHost, e: ActiveEncounter): Vec2 {\n    return nativeHost.swarmEntryPoint(e.pos, e.def.extract!.swarm.entryRadius);\n  }",
