      "source": "private insideGrantedPocket(a: Actor, id: string, pockets = this.grantedPocketsFor(a)): boolean {\n    return pockets.some(p => p.grantId === id && p.tier === a.tier\n      && Math.hypot(p.x - a.pos.x, p.y - a.pos.y) <= p.r);\n  }",
      "output": "export function sceneInsideGrantedPocket(nativeHost:NativeSceneFrameHost, a: Actor, id: string, pockets = nativeHost.grantedPocketsFor(a)): boolean {\n    return pockets.some(p => p.grantId === id && p.tier === a.tier\n      && Math.hypot(p.x - a.pos.x, p.y - a.pos.y) <= p.r);\n  }",
