      "source": "localZoneAt(pos: Vec2): ZoneDef {\n    const town = this.massRuntime?.settlement;\n    return town?.contains(pos.x, pos.y) ? town.zone\n      : this.massRuntime?.nativeFeatures?.contextAt(this.massRuntime.walk.at(pos.x,pos.y))\n        ?? this.massRuntime?.geography?.contextAt(this.massRuntime.walk.at(pos.x,pos.y)) ?? this.zone;\n  }",
      "output": "export function sceneLocalZoneAt(nativeHost:NativeSceneFrameHost, pos: Vec2): ZoneDef {\n    const town = nativeHost.massRuntime?.settlement;\n    return town?.contains(pos.x, pos.y) ? town.zone\n      : nativeHost.massRuntime?.nativeFeatures?.contextAt(nativeHost.massRuntime.walk.at(pos.x,pos.y))\n        ?? nativeHost.massRuntime?.geography?.contextAt(nativeHost.massRuntime.walk.at(pos.x,pos.y)) ?? nativeHost.zone;\n  }",
