      "fn": "sceneGrantVestige",
      "line": 41099,
      "source": "grantVestige(seat: Seat, id: string, count: number): void {\n    const def = VESTIGES[id];\n    if (!def || count <= 0) return;\n    seat.meta.vestiges[id] = (seat.meta.vestiges[id] ?? 0) + count;\n    this.text(seat.actor.pos, `${def.glyph} ${def.name}${count > 1 ? ` ×${count}` : ''}`, def.color, 13, 'pickup');\n    notePickup(this.pickupFeed, seat.id, `${def.glyph} ${def.name}`, def.color, this.time, count);\n    this.markMetaDirty(seat);\n  }",
      "output": "export function sceneGrantVestige(nativeHost:NativeSceneFrameHost, seat: Seat, id: string, count: number): void {\n    const def = VESTIGES[id];\n    if (!def || count <= 0) return;\n    seat.meta.vestiges[id] = (seat.meta.vestiges[id] ?? 0) + count;\n    nativeHost.text(seat.actor.pos, `${def.glyph} ${def.name}${count > 1 ? ` ×${count}` : ''}`, def.color, 13, 'pickup');\n    notePickup(nativeHost.pickupFeed, seat.id, `${def.glyph} ${def.name}`, def.color, nativeHost.time, count);\n    nativeHost.markMetaDirty(seat);\n  }",
