      "source": "private tryMergeMemoryItem(seat: Seat, item: ItemInstance): boolean {\n    const kind = memoryKindOf(item);\n    if (!kind || !item.mem) return false;\n    const pouch = findMemoryItem(seat.meta.items, kind);\n    if (!pouch) return false;\n    mergeMemory(pouch, item.mem);\n    this.noteMemoryPickup(seat, kind, pouch.mem!.length);\n    this.markMetaDirty(seat);\n    return true;\n  }",
      "output": "export function sceneTryMergeMemoryItem(nativeHost:NativeSceneFrameHost, seat: Seat, item: ItemInstance): boolean {\n    const kind = memoryKindOf(item);\n    if (!kind || !item.mem) return false;\n    const pouch = findMemoryItem(seat.meta.items, kind);\n    if (!pouch) return false;\n    mergeMemory(pouch, item.mem);\n    nativeHost.noteMemoryPickup(seat, kind, pouch.mem!.length);\n    nativeHost.markMetaDirty(seat);\n    return true;\n  }",
