      "group": "EffectsTick",
      "name": "isBankedRelicEcho",
      "fn": "sceneIsBankedRelicEcho",
      "line": 40645,
      "source": "private isBankedRelicEcho(item: ItemInstance): boolean {\n    if (!isRelic(item)) return false;\n    const scope = this.meta.relicScope ?? (this.meta.charId || 'run:' + this.manifest.seed);\n    return !!item.relicKey || this.account.reliquary.released.includes('legacy:' + scope + ':' + item.uid)\n      || this.account.reliquary.items.some(i => i.relicKey === 'legacy:' + scope + ':' + item.uid);\n  }",
      "output": "export function sceneIsBankedRelicEcho(nativeHost:NativeSceneFrameHost, item: ItemInstance): boolean {\n    if (!isRelic(item)) return false;\n    const scope = nativeHost.meta.relicScope ?? (nativeHost.meta.charId || 'run:' + nativeHost.manifest.seed);\n    return !!item.relicKey || nativeHost.account.reliquary.released.includes('legacy:' + scope + ':' + item.uid)\n      || nativeHost.account.reliquary.items.some(i => i.relicKey === 'legacy:' + scope + ':' + item.uid);\n  }",
