      "source": "private inGrantedRefuge(a: Actor, resource: string): boolean {\n    return Object.values(POCKET_GRANTS).some(def => def.resource === resource\n      && a.sheet.get(pocketGrantStat(def.id)) > 0 && this.insideGrantedPocket(a, def.id));\n  }",
