      "sourceSha256": "49f2da971918b475c178d591e7c4fa8e3d4a0d019378099d1d9cd6e3d16f1c89",
      "outputSha256": "5df9f60efdf5a81c727092d0df82bebafeeb6c63f5aa2a2ca0e4327a871a261b"
