    {
      "group": "EffectsTick",
      "name": "setTracksArmed",
      "fn": "sceneSetTracksArmed",
      "line": 48065,
      "source": "setTracksArmed(tag: string, armed: boolean): void {\n    for (const tr of this.tracks) {\n      if (tr.spec.tag !== tag || tr.armed === armed) continue;\n      tr.armed = armed;\n      for (const r of tr.riders) {\n        const pose = trackPose(tr, this.time, r.phase, r.def);\n        const reach = r.def.surface.kind === 'circle'\n          ? r.def.surface.r : Math.max(r.def.surface.hw, r.def.surface.hh);\n        this.flashes.push({ pos: vec(pose.x, pose.y), radius: reach * 1.4, color: r.def.color ?? '#cfc4ae', life: 0.4, maxLife: 0.4 });\n      }\n    }\n  }",
      "output": "export function sceneSetTracksArmed(nativeHost:NativeSceneFrameHost, tag: string, armed: boolean): void {\n    for (const tr of nativeHost.tracks) {\n      if (tr.spec.tag !== tag || tr.armed === armed) continue;\n      tr.armed = armed;\n      for (const r of tr.riders) {\n        const pose = trackPose(tr, nativeHost.time, r.phase, r.def);\n        const reach = r.def.surface.kind === 'circle'\n          ? r.def.surface.r : Math.max(r.def.surface.hw, r.def.surface.hh);\n        nativeHost.flashes.push({ pos: vec(pose.x, pose.y), radius: reach * 1.4, color: r.def.color ?? '#cfc4ae', life: 0.4, maxLife: 0.4 });\n      }\n    }\n  }",
      "sourceSha256": "19c576f13a332aa82b3a464a03225284158f1bd3f023d24bc0d955665e19df97",
      "outputSha256": "83155917dd30648a6f8faee85e8b882e532ad7bf43f662fc2a03cdf437baaf88"
    },
    {
      "group": "EffectsTick",
      "name": "collapseFloor",
      "fn": "sceneCollapseFloor",
      "line": 48216,
      "source": "collapseFloor(cells: { x: number; y: number; r?: number }[], delaySec: number,\n    presserId?: number, visualOnly?: boolean, tier = 0): void {\n    // `tier`: the story the false floor lies on (the sovereignty gate) —\n    // only feet on it drop; a storey walker over a ground pit is unmoved.\n    const plant = (): void => {\n      const made: Doodad[] = [];\n      for (const c of cells) {\n        const r = c.r ?? 26;\n        // Idempotent (the 20 Hz mirror re-runs): a gap already yawning here\n        // is not planted twice.\n        if (this.doodads.some(d => d.kind === 'ruin_floor_gap' && !d.gone\n          && Math.abs(d.pos.x - c.x) < 8 && Math.abs(d.pos.y - c.y) < 8)) continue;\n        const d = { pos: vec(c.x, c.y), radius: r, kind: 'ruin_floor_gap', fall: true } as Doodad;\n        this.doodads.push(d);\n        made.push(d);\n      }\n      if (!made.length) return;\n      this.markDoodadsChanged();\n      for (const d of made) {\n        this.flashes.push({ pos: vec(d.pos.x, d.pos.y), radius: d.radius + 10, color: '#141019', life: 0.5, maxLife: 0.5 });\n        // THE DISSOLUTION GRAMMAR (D1): the drop speaks the dust voice (one\n        // accent channel — the floor's own give-way breath; clients too).\n        this.flashes.push({ pos: vec(d.pos.x, d.pos.y), radius: d.radius * 1.6, color: '#8a7a5c', life: 0.45, maxLife: 0.45, fx: 'dust' });\n      }\n      this.shake = Math.max(this.shake, 1.6);\n      if (visualOnly) return;\n      const presser = presserId !== undefined\n        ? this.actors.find(a => a.id === presserId && !a.dead) : undefined;\n      for (const a of this.actors) {\n        if (a.dead || a.downed || a.flying || a.dash || a.leap || a.caromRun) continue;\n        if (a.tier !== tier) continue; // its own story's feet (the sovereignty gate)\n        const g = made.find(d => dist(a.pos, d.pos) <= d.radius);\n        if (!g) continue;\n        const dir = Math.atan2(g.pos.y - a.pos.y, g.pos.x - a.pos.x);\n        this.pushActor(a, Number.isFinite(dir) ? dir : 0, 70, presser);\n      }\n    };\n    if (delaySec <= 0) { plant(); return; }\n    // The crumble telegraph: the shiver the dash escapes — and, THE\n    // DISSOLUTION GRAMMAR (D1), the DRAWN PRE-CRACK: every doomed cell cracks\n    // from its heart over the delay (dissolveFloorCrackView — the caption\n    // \"the floor gives way\" retired; the crack IS the sentence).\n    for (const c of cells) {\n      this.flashes.push({ pos: vec(c.x, c.y), radius: (c.r ?? 26) * 0.9, color: '#8a7a5c', life: delaySec, maxLife: delaySec });\n    }\n    if (cells.length) {\n      this.dissolveFloorCracks.push({\n        cells: cells.map(c => ({ x: c.x, y: c.y, r: c.r ?? 26 })),\n        at: this.time, until: this.time + delaySec,\n      });\n    }\n    this.trapDeferred.push({ at: this.time + delaySec, run: plant });\n  }",
      "output": "export function sceneCollapseFloor(nativeHost:NativeSceneFrameHost, cells: { x: number; y: number; r?: number }[], delaySec: number,\n    presserId?: number, visualOnly?: boolean, tier = 0): void {\n    // `tier`: the story the false floor lies on (the sovereignty gate) —\n    // only feet on it drop; a storey walker over a ground pit is unmoved.\n    const plant = (): void => {\n      const made: Doodad[] = [];\n      for (const c of cells) {\n        const r = c.r ?? 26;\n        // Idempotent (the 20 Hz mirror re-runs): a gap already yawning here\n        // is not planted twice.\n        if (nativeHost.doodads.some(d => d.kind === 'ruin_floor_gap' && !d.gone\n          && Math.abs(d.pos.x - c.x) < 8 && Math.abs(d.pos.y - c.y) < 8)) continue;\n        const d = { pos: vec(c.x, c.y), radius: r, kind: 'ruin_floor_gap', fall: true } as Doodad;\n        nativeHost.doodads.push(d);\n        made.push(d);\n      }\n      if (!made.length) return;\n      nativeHost.markDoodadsChanged();\n      for (const d of made) {\n        nativeHost.flashes.push({ pos: vec(d.pos.x, d.pos.y), radius: d.radius + 10, color: '#141019', life: 0.5, maxLife: 0.5 });\n        // THE DISSOLUTION GRAMMAR (D1): the drop speaks the dust voice (one\n        // accent channel — the floor's own give-way breath; clients too).\n        nativeHost.flashes.push({ pos: vec(d.pos.x, d.pos.y), radius: d.radius * 1.6, color: '#8a7a5c', life: 0.45, maxLife: 0.45, fx: 'dust' });\n      }\n      nativeHost.shake = Math.max(nativeHost.shake, 1.6);\n      if (visualOnly) return;\n      const presser = presserId !== undefined\n        ? nativeHost.actors.find(a => a.id === presserId && !a.dead) : undefined;\n      for (const a of nativeHost.actors) {\n        if (a.dead || a.downed || a.flying || a.dash || a.leap || a.caromRun) continue;\n        if (a.tier !== tier) continue; // its own story's feet (the sovereignty gate)\n        const g = made.find(d => dist(a.pos, d.pos) <= d.radius);\n        if (!g) continue;\n        const dir = Math.atan2(g.pos.y - a.pos.y, g.pos.x - a.pos.x);\n        nativeHost.pushActor(a, Number.isFinite(dir) ? dir : 0, 70, presser);\n      }\n    };\n    if (delaySec <= 0) { plant(); return; }\n    // The crumble telegraph: the shiver the dash escapes — and, THE\n    // DISSOLUTION GRAMMAR (D1), the DRAWN PRE-CRACK: every doomed cell cracks\n    // from its heart over the delay (dissolveFloorCrackView — the caption\n    // \"the floor gives way\" retired; the crack IS the sentence).\n    for (const c of cells) {\n      nativeHost.flashes.push({ pos: vec(c.x, c.y), radius: (c.r ?? 26) * 0.9, color: '#8a7a5c', life: delaySec, maxLife: delaySec });\n    }\n    if (cells.length) {\n      nativeHost.dissolveFloorCracks.push({\n        cells: cells.map(c => ({ x: c.x, y: c.y, r: c.r ?? 26 })),\n        at: nativeHost.time, until: nativeHost.time + delaySec,\n      });\n    }\n    nativeHost.trapDeferred.push({ at: nativeHost.time + delaySec, run: plant });\n  }",
      "sourceSha256": "247b17595a2d3c3cbda32f774acb475e254752bed15d9c9cb09ce3e5a603abdf",
      "outputSha256": "a6ec4db7d0c2be740bc80a56f4757b6ddc84625b7e63d4d182f8406eeb933c29"
    },
    {
      "group": "EffectsTick",
      "name": "clearDoodadsNear",
      "fn": "sceneClearDoodadsNear",
      "line": 48272,
      "source": "clearDoodadsNear(kind: string, at: { x: number; y: number }, r: number): void {\n    let any = false;\n    for (const d of this.doodads) {\n      if (d.kind !== kind || d.gone) continue;\n      if (dist(d.pos, at) > r) continue;\n      d.gone = true;\n      any = true;\n    }\n    if (any) this.markDoodadsChanged();\n  }",
      "output": "export function sceneClearDoodadsNear(nativeHost:NativeSceneFrameHost, kind: string, at: { x: number; y: number }, r: number): void {\n    let any = false;\n    for (const d of nativeHost.doodads) {\n      if (d.kind !== kind || d.gone) continue;\n      if (dist(d.pos, at) > r) continue;\n      d.gone = true;\n      any = true;\n    }\n    if (any) nativeHost.markDoodadsChanged();\n  }",
      "sourceSha256": "06b4a5c4ce429d4d00f68a923b3e089732867938743eb5fb271e54567008d5c2",
      "outputSha256": "8ae5917c0391d7695c624a75ad3d4f3fdddb8f71ad9afeb45ffbba578aba38ae"
    }
